parameters.jsonBody:
={{ {
  model: $('Initialize Parameters').first().json.ollamaModel,
  messages: [
    { role: 'system', content: 'You are a Business Architect. Output JSON matching ArchiMate business layer schema with capabilities, actors, processes, services. No extra keys.' },
    { role: 'user', content: 'BRD: ' + JSON.stringify($json.brd).slice(0, 12000) }
  ],
  stream: false,
  format: { type: 'object', required: ['capabilities','actors','processes','services'], properties: { capabilities: { type: 'array' }, actors: { type: 'array' }, processes: { type: 'array' }, services: { type: 'array' }, relationships: { type: 'array' } } },
  options: { temperature: $('Initialize Parameters').first().json.ollamaTemperature, seed: $('Initialize Parameters').first().json.ollamaSeed }
} }}

parameters.jsCode:
const raw = $json.message?.content;
let arch; try { arch = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return [{ json: { valid: false, businessArch: null } }]; }
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < (s||'').length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };
return [{ json: { valid: true, businessArch: arch, businessArchHash: fnv1a(JSON.stringify(arch)) } }];

