// Convert all architecture layers to ArchiMate XML
const ctx = $('Pass Context').first().json;
const biz = $('Validate Business Arch').first().json.businessArch || {};
const app = $('Validate Application Arch').first().json.applicationArch || {};
const data = $('Validate Data Arch').first().json.dataArch || {};
const infra = $('Validate Infrastructure Arch').first().json.infraArch || {};

const uuid = () => 'id-' + Math.random().toString(36).substr(2, 9);

let elements = '';
let relationships = '';

// Business layer elements
for (const cap of (biz.capabilities || [])) elements += `<element xsi:type="archimate:Capability" id="${uuid()}" name="${(cap.name||cap).replace(/"/g,'&quot;')}"/>\n`;
for (const actor of (biz.actors || [])) elements += `<element xsi:type="archimate:BusinessActor" id="${uuid()}" name="${(actor.name||actor).replace(/"/g,'&quot;')}"/>\n`;
for (const proc of (biz.processes || [])) elements += `<element xsi:type="archimate:BusinessProcess" id="${uuid()}" name="${(proc.name||proc).replace(/"/g,'&quot;')}"/>\n`;
for (const svc of (biz.services || [])) elements += `<element xsi:type="archimate:BusinessService" id="${uuid()}" name="${(svc.name||svc).replace(/"/g,'&quot;')}"/>\n`;

// Application layer elements
for (const comp of (app.components || [])) elements += `<element xsi:type="archimate:ApplicationComponent" id="${uuid()}" name="${(comp.name||comp).replace(/"/g,'&quot;')}"/>\n`;
for (const iface of (app.interfaces || [])) elements += `<element xsi:type="archimate:ApplicationInterface" id="${uuid()}" name="${(iface.name||iface).replace(/"/g,'&quot;')}"/>\n`;
for (const obj of (app.dataObjects || [])) elements += `<element xsi:type="archimate:DataObject" id="${uuid()}" name="${(obj.name||obj).replace(/"/g,'&quot;')}"/>\n`;

// Data layer elements
for (const ent of (data.dataEntities || [])) elements += `<element xsi:type="archimate:DataObject" id="${uuid()}" name="${(ent.name||ent).replace(/"/g,'&quot;')}"/>\n`;
for (const db of (data.databases || [])) elements += `<element xsi:type="archimate:Artifact" id="${uuid()}" name="${(db.name||db).replace(/"/g,'&quot;')}"/>\n`;

// Infrastructure layer elements
for (const node of (infra.nodes || [])) elements += `<element xsi:type="archimate:Node" id="${uuid()}" name="${(node.name||node).replace(/"/g,'&quot;')}"/>\n`;
for (const net of (infra.networks || [])) elements += `<element xsi:type="archimate:CommunicationNetwork" id="${uuid()}" name="${(net.name||net).replace(/"/g,'&quot;')}"/>\n`;
for (const dep of (infra.deployments || [])) elements += `<element xsi:type="archimate:SystemSoftware" id="${uuid()}" name="${(dep.name||dep).replace(/"/g,'&quot;')}"/>\n`;
for (const art of (infra.artifacts || [])) elements += `<element xsi:type="archimate:Artifact" id="${uuid()}" name="${(art.name||art).replace(/"/g,'&quot;')}"/>\n`;

const xml = `<?xml version="1.0" encoding="UTF-8"?>
<archimate:model xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:archimate="http://www.archimatetool.com/archimate" name="${ctx.projectName}" id="${uuid()}">
  <folder name="Business" type="business">
${elements}
  </folder>
  <folder name="Relations" type="relations">
${relationships}
  </folder>
</archimate:model>`;

const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };

return [{ json: { ...ctx, archimateXml: xml, archimateXmlHash: fnv1a(xml) } }];

const ctx = $('Convert to ArchiMate XML').first().json;
const xml = ctx.archimateXml;
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;
const repoDir = '/opt/workspace/software-delivery';
const projectDir = repoDir + '/' + projectSlug + '-docs';
const remote = 'git@github.com:shlapolosa/software-delivery.git';

let sh = 'set -e\nmkdir -p /opt/workspace\n';
sh += "if [ ! -d '" + repoDir + "/.git' ]; then git clone '" + remote + "' '" + repoDir + "'; fi\n";
sh += "cd '" + repoDir + "'\ngit fetch origin\n";
sh += "git checkout -B '" + projectSlug + "' 'origin/" + projectSlug + "' 2>/dev/null || git checkout -B '" + projectSlug + "'\n";
sh += "mkdir -p '" + projectDir + "/architecture' '" + repoDir + "/org-architecture'\n";

// Write project-specific full.archimate
sh += "cat > '" + projectDir + "/architecture/full.archimate' <<'EOF_" + jobId + "'\n" + xml + "\nEOF_" + jobId + "\n";

// Write org-level full.archimate (merge would go here in production)
sh += "cat > '" + repoDir + "/org-architecture/full.archimate' <<'EOF_" + jobId + "'\n" + xml + "\nEOF_" + jobId + "\n";

sh += "git add '" + projectSlug + "-docs/architecture' 'org-architecture'\n";
sh += "git commit -m 'Add architecture for " + projectSlug + " (job " + jobId + ")' || true\n";
sh += "git push -u origin '" + projectSlug + "'\n";

return [{ json: { ...ctx, gitScript: sh } }];
